function exportJSON(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function settingsPanel(){sheet(`<div class="eyebrow">OUR KIND OF ROAD TRIP</div><h2 class="sheet-title">Make it yours.</h2><button class="secondary wide" id="settings-position">Change current town & direction</button><label class="field">Average planning pace<select id="pace"><option value="25" ${state.speed===25?'selected':''}>25 mph - back roads and slow towns</option><option value="35" ${state.speed===35?'selected':''}>35 mph - unhurried (default)</option><option value="45" ${state.speed===45?'selected':''}>45 mph - steady going</option></select></label><p class="small-note">An estimate, not a measured speed or navigation ETA.</p><label class="check"><input id="passenger" type="checkbox" ${state.passenger?'checked':''}> Passenger mode on this phone</label><p class="small-note">A browsing mode for your travel partner on the same device. No cross-phone syncing yet.</p><label class="check"><input id="star-alert" type="checkbox" ${state.alerts?'checked':''}> In-app heads-up for pinned starred stops</label><label class="check"><input id="voice-alert" type="checkbox" ${state.voice?'checked':''}> Speak those heads-ups</label><p class="small-note">Alerts need foreground GPS and a precise personal place pin. They do not provide turnoff instructions or background notifications.</p><div class="eyebrow" style="margin-top:20px">OUR FAVORITE THINGS</div>${['Diner','Americana','Neon','Motor court','Photo stop'].map(t=>'<label class="check"><input class="pref" value="'+t+'" type="checkbox" '+(state.preferences.includes(t)?'checked':'')+'>'+t+'</label>').join('')}<button class="primary wide" id="save-settings">Save preferences</button><hr style="border:0;border-top:1px solid #d9dfcf;margin:25px 0"><h3>Offline road pack</h3><p class="sheet-intro">The app, full stop catalog, histories, and planner are saved after your first successful online visit. Photos, live maps, calling, and booking links need connectivity. This is not an offline turn-by-turn navigation pack.</p><div id="offline-status" class="offline-indicator"></div><button class="secondary wide" id="offline-refresh">Check offline pack</button>`);$('#settings-position').onclick=positionPanel;$('#save-settings').onclick=()=>{state.speed=+$('#pace').value;state.passenger=$('#passenger').checked;state.alerts=$('#star-alert').checked;state.voice=$('#voice-alert').checked;state.preferences=[...document.querySelectorAll('.pref:checked')].map(x=>x.value);persist();renderDrive();toast('Your road-trip preferences are saved.');closeSheet()};$('#offline-refresh').onclick=async()=>{if(!('serviceWorker'in navigator)){toast('Offline caching is unavailable in this browser.');return}try{const r=await navigator.serviceWorker.ready;await r.update();$('#offline-status').textContent='Offline app pack is registered. Revisit once online before testing airplane mode.'}catch{toast('Offline pack could not be checked.')}};$('#offline-status').textContent=navigator.serviceWorker?.controller?'Offline app pack is active.':'Offline pack activates after a successful HTTPS visit and reload.'}
function gpsPanel(){sheet(`<div class="eyebrow">LEAVE A TRAIL. COLLECT THE MEMORIES.</div><h2 class="sheet-title">Your breadcrumbs.</h2><p class="sheet-intro">Locations stay on this device. iPhone tracking pauses if you switch to navigation or lock the screen. No continuous background tracking in this web build.</p><button id="gps-toggle" class="primary wide">${gpsOn?'Stop GPS tracking':'Start GPS tracking'}</button><p id="gps-status" class="small-note" role="status">${gpsOn?'Waiting for fresh location updates.':'GPS is off.'}</p><svg id="trail-svg" class="trail" viewBox="0 0 320 160" role="img" aria-label="Your actual recorded breadcrumb points, north up, without a street map"></svg><p class="small-note" id="trail-count"></p><details><summary>Precise pins & automatic check-ins</summary><p class="sheet-intro">The seed catalog has no verified venue coordinates. Town centers never count as places visited. Confirm a precise pin while physically at a venue; two good fixes within 150 meters, at least 3 seconds apart, can then mark it visited. A pass-by confirms proximity, not entry.</p><label class="field">I am physically at<select id="pin-place">${data.places.filter(p=>p.operatingStatus!=='reported_closed').map(p=>'<option value="'+p.id+'">'+esc(p.name)+' - '+esc(p.town)+'</option>').join('')}</select></label><button id="pin-here" class="secondary wide">Confirm this place is here</button><p class="small-note">${state.pins.length} personal pins saved.</p></details><div class="filter-row" style="padding:16px 0"><button class="secondary" id="export-trail">Export trail</button><button class="secondary" id="clear-trail">Clear trail</button></div><p class="small-note">North up. Gaps are not connected. Last 10,000 samples retained.</p>`);$('#gps-toggle').onclick=()=>{gpsOn?stopGPS():startGPS();$('#gps-toggle').textContent=gpsOn?'Stop GPS tracking':'Start GPS tracking'};$('#pin-here').onclick=()=>{if(!gpsOn||!latestGPS||!KicksGPS.valid(latestGPS,Date.now())||latestGPS.accuracy>35){toast('Start GPS and wait for a fresh fix accurate to 35 meters or better.');return}const p=data.places.find(p=>p.id===$('#pin-place').value);if(!confirm('Confirm that you are physically at '+p.name+' now?'))return;state.pins=state.pins.filter(x=>x.id!==p.id);state.pins.push({id:p.id,lat:latestGPS.lat,lon:latestGPS.lon,accuracy:latestGPS.accuracy,verification:'user-confirmed'});engine.reset();persist();toast('Precise personal pin saved.');gpsPanel()};$('#export-trail').onclick=()=>exportJSON('get-your-kicks-trail.geojson',{type:'FeatureCollection',features:state.trace.map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lon,p.lat]},properties:{time:new Date(p.time).toISOString(),accuracyMeters:p.accuracy,segmentStart:!!p.break}}))});$('#clear-trail').onclick=()=>{if(confirm('Clear GPS trail and GPS events? Passport visits and place pins will remain.')){state.trace=[];state.gpsEvents=[];engine.reset();breakTrail=true;persist();drawTrail()}};drawTrail()}
function gpsStatus(t){$('#track-label').textContent=t;if($('#gps-status'))$('#gps-status').textContent=t}
function startGPS(){if(!window.isSecureContext||!navigator.geolocation){toast('GPS needs the HTTPS site and location support.');return}if(gpsWatch!==null)return;gpsOn=true;breakTrail=true;engine.reset();gpsStatus('Requesting location permission...');gpsWatch=navigator.geolocation.watchPosition(onGPS,e=>{latestGPS=null;breakTrail=true;engine.reset();if(e.code===1){stopGPS();gpsStatus('Location denied. Choose a planning town manually.')}else gpsStatus('GPS signal unavailable. Check-ins paused.');if($('#gps-toggle'))$('#gps-toggle').textContent=gpsOn?'Stop GPS tracking':'Start GPS tracking'},{enableHighAccuracy:true,maximumAge:0,timeout:15000})}
function stopGPS(){gpsOn=false;if(gpsWatch!==null)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;latestGPS=null;engine.reset();breakTrail=true;persist();gpsStatus('GPS is off')}
function onGPS(pos){if(!gpsOn||document.hidden)return;const c=pos.coords,p={lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,time:pos.timestamp};let out=engine.update(p,state.pins,state.visited);if(!out.accepted){gpsStatus('Waiting for a fresh, accurate GPS fix.');return}latestGPS=p;lastGPS=Date.now();let last=state.trace.at(-1);if(!last||breakTrail||p.time-last.time>=10000||KicksGPS.distance(p,last)>=20){state.trace.push({...p,break:breakTrail||!last||p.time-last.time>60000||KicksGPS.distance(p,last)/Math.max(1,(p.time-last.time)/1000)>85});state.trace=state.trace.slice(-10000);breakTrail=false}out.hits.forEach(id=>{if(!state.visited.includes(id)){state.visited.push(id);state.gpsEvents.push({id,time:p.time,method:'gps-proximity'});toast('Passed '+data.places.find(x=>x.id===id).name+' - collected in your passport.')}});state.gpsEvents=state.gpsEvents.slice(-500);if(state.alerts)state.pins.forEach(pin=>{const place=data.places.find(x=>x.id===pin.id);if(place?.mustDo&&KicksPlanner.ahead(place,current,state.direction)&&!alerted.has(pin.id)&&KicksGPS.distance(p,pin)<1600){alerted.add(pin.id);const msg='Starred stop nearby: '+place.name+'. Check the road and a safe place to stop.';toast(msg);if(state.voice&&'speechSynthesis'in window)speechSynthesis.speak(new SpeechSynthesisUtterance(msg))}});gpsStatus('Recording | accuracy '+Math.round(p.accuracy)+' m');drawTrail();renderPassport();if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=null;persist()},5000)}
function drawTrail(){if(!$('#trail-svg'))return;$('#trail-count').textContent=state.trace.length+' breadcrumbs \u00b7 '+state.gpsEvents.length+' GPS check-ins';if(!state.trace.length){$('#trail-svg').innerHTML='<text x="160" y="80" text-anchor="middle" font-size="12" fill="#68816b">Your trail will appear here</text>';return}const c=Math.max(.01,Math.cos(state.trace[0].lat*Math.PI/180)),xs=state.trace.map(p=>p.lon*c),ys=state.trace.map(p=>-p.lat),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),scale=Math.min(290/Math.max(maxx-minx,.0001),130/Math.max(maxy-miny,.0001)),xy=p=>[(p.lon*c-(minx+maxx)/2)*scale+160,(-p.lat-(miny+maxy)/2)*scale+80];let path=state.trace.map((p,i)=>{let q=xy(p);return (!i||p.break?'M':'L')+q[0].toFixed(1)+' '+q[1].toFixed(1)}).join(' '),last=xy(state.trace.at(-1));$('#trail-svg').innerHTML='<path d="'+path+'" fill="none" stroke="#249c85" stroke-width="3"/><circle cx="'+last[0]+'" cy="'+last[1]+'" r="5" fill="#b58126"/>'}
function about(){sheet(`<div class="eyebrow">GET YOUR KICKS / GITHUB TEST BUILD</div><h2 class="sheet-title">A little neon.<br>A lot of America.</h2><p class="sheet-intro">${data.stats.total} discovery stops, ${data.stats.food} food stops, ${data.stats.stays} lodging options, and ${data.stats.mustDo} editorial Must Do picks. Stars celebrate Route 66 character; they are not customer ratings.</p><h3>What this build does</h3><p class="sheet-intro">Forward-town recommendations, stars-first Eat/Sleep planning, earlier-stop suggestions, overnight bundles, saved stops, notes, personal photos, audio reading, passport badges, foreground GPS breadcrumbs and personal-pin check-ins, and an offline catalog.</p><h3>What is still approximate</h3><p class="sheet-intro">The map is a schematic town overview, not the historic road geometry. Planning uses town-to-town distances and an adjustable pace; there is no live traffic or street-routing service. Same-town stops are conservatively excluded. Exact detours, route gaps, sunset times, live openings, and hotel prices/availability are not supplied. No live fuel-gap or last-chance claims are generated without verified service data.</p><h3>Your privacy</h3><p class="sheet-intro">GPS, notes, photos, favorites, and passport stay in this browser. Export to back them up. Opening Maps, Waze, a booking page, or an external photo contacts that service. No account, server-side tracking, or cross-device sync.</p><div class="detail-links">${a('hotels-restaurants.csv','Download food & hotel CSV')}${a('directory.sqlite','Download database')}${a('https://picryl.com/media/scene-outside-delgadillos-snow-cap-drive-in-restaurant-a-historic-eatery-and-a9fa48','Snow Cap photo & credit')}</div><p class="small-note">Photo: Carol M. Highsmith Archive, Library of Congress, via PICRYL (no known publication restrictions). Other venue images are explicitly labelled illustrations.</p>`)}
function renderAll(){renderDrive();renderDiscover();renderPassport()}
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;if(t.dataset.screen)view(t.dataset.screen);if(t.dataset.save){let id=t.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();t.textContent=state.saved.includes(id)?'Saved':'Save';t.setAttribute('aria-pressed',String(state.saved.includes(id)));if(activeScreen==='passport')renderPassport()}if(t.dataset.detail)details(t.dataset.detail);if(t.dataset.next){const p=data.places.find(x=>x.id===t.dataset.next);if(!KicksPlanner.ahead(p,current,state.direction)){toast('That stop is not ahead of your current planning town.');return}nextId=p.id;closeSheet();view('drive');renderDrive()}if(t.dataset.kind){kind=t.dataset.kind;limit=20;document.querySelectorAll('[data-kind]').forEach(b=>b.classList.toggle('active',b===t));renderDiscover()}if(t.dataset.quick){kind=t.dataset.quick;document.querySelectorAll('[data-kind]').forEach(b=>b.classList.toggle('active',b.dataset.kind===kind));view('discover')}if(t.dataset.service){const n=nodes.filter(n=>state.direction*(n.order-current.order)>0).sort((a,b)=>state.direction*(a.order-b.order))[0];if(!n){toast('No next town in the catalog.');return}sheet('<h2 class="sheet-title">'+(t.dataset.service==='gas stations'?'Fuel ahead':'A break ahead')+'</h2><p class="sheet-intro">Search live listings around '+esc(n.town)+', '+n.state+'. This search is centered on an upcoming town, but external results may include places behind you. Check their direction before navigating. No verified service-gap estimate is available.</p><div class="detail-links">'+a('https://www.google.com/maps/search/?'+new URLSearchParams({api:'1',query:t.dataset.service+' in '+n.town+', '+n.state}),'Open live listings')+'</div>')}});
$('#sheet-close').onclick=closeSheet;$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom)closeSheet()}});$('#position-open').onclick=positionPanel;$('#gps-map').onclick=positionPanel;$('#settings-open').onclick=settingsPanel;$('#plan-open').onclick=openPlan;$('#breadcrumbs-open').onclick=gpsPanel;$('#evening-open').onclick=()=>nightPanel();$('#about-open').onclick=about;$('#search').oninput=()=>{limit=20;renderDiscover()};$('#must-toggle').onclick=()=>{onlyStars=!onlyStars;$('#must-toggle').setAttribute('aria-pressed',String(onlyStars));renderDiscover()};$('#vibe').onchange=e=>{vibe=e.target.value;renderDiscover()};$('#more-results').onclick=()=>{limit+=20;renderDiscover()};$('#show-saved').onclick=()=>{const list=data.places.filter(p=>state.saved.includes(p.id));sheet('<h2 class="sheet-title">Our possibilities.</h2><p class="sheet-intro">Saved places stay here even after you pass them. Only places still ahead offer navigation recommendations.</p>'+list.map(p=>KicksPlanner.ahead(p,current,state.direction)?listCard(p):'<div class="list-card"><h3>'+esc(p.name)+'</h3><p>'+esc(p.town)+', '+p.state+' - not in a forward town from your current position.</p><button class="text-button" data-detail="'+p.id+'">Open memory & details</button></div>').join('')+(!list.length?'<div class="empty">Save a diner, a motel, or a whole evening along the way.</div>':''))};
$('#export-passport').onclick=()=>exportJSON('get-your-kicks-passport.json',state);$('#import-passport').onchange=async()=>{try{const d=JSON.parse(await $('#import-passport').files[0].text());if(!Array.isArray(d.saved)||!Array.isArray(d.visited))throw Error();if(!confirm('Replace this browser\'s saved stops, visits, notes, and photos with this passport?'))return;const ids=new Set(data.places.map(p=>p.id));state.saved=[...new Set(d.saved.filter(x=>ids.has(x)))];state.visited=[...new Set(d.visited.filter(x=>ids.has(x)))];state.notes=Object.fromEntries(Object.entries(d.notes||{}).filter(([id,v])=>ids.has(id)&&typeof v==='string').map(([id,v])=>[id,v.slice(0,5000)]));state.photos=Object.fromEntries(Object.entries(d.photos||{}).filter(([id,v])=>ids.has(id)&&typeof v==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(v)));persist();renderAll();toast('Passport imported.')}catch{toast('That file could not be imported. Choose a Get Your Kicks passport JSON file.')}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(gpsWatch!==null)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;latestGPS=null;engine.reset();breakTrail=true;persist();if(gpsOn)gpsStatus('Paused in background')}else if(gpsOn)startGPS()});window.addEventListener('pagehide',()=>{if(gpsWatch!==null)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;persist()});setInterval(()=>{if(gpsOn&&!document.hidden&&lastGPS&&Date.now()-lastGPS>30000){latestGPS=null;engine.reset();breakTrail=true;gpsStatus('GPS is stale. Check-ins paused.')}},10000);function connection(){$('#connection').hidden=navigator.onLine}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
