forward=function(){return positionReady?originalForward():[]};
updateCurrent=function(){if(!positionReady)return;originalUpdate();if(positionFix){current={...current,lat:positionFix.lat,lon:positionFix.lon};$('#position-open').textContent='GPS near '+current.town+' - refresh location';$('#direction-label').textContent=(state.direction===1?'WESTBOUND':'EASTBOUND')+' - '+current.state;$('#road-note').textContent='Using your actual GPS location near '+current.town+'. Stop direction and travel estimates are still town-based because exact historic-road geometry and venue pins are not verified.'}};
renderDrive=function(){if(positionReady){originalDrive();return}current=null;$('#direction-label').textContent='YOUR LOCATION FIRST';$('#position-open').textContent=positionBusy?'Finding your location...':'Use my actual location';$('#road-map').innerHTML='<rect width="700" height="340" fill="#e6ead9"/><circle cx="350" cy="140" r="38" fill="#d2e3d3"/><circle cx="350" cy="140" r="10" fill="#3b9cc1"/><text x="350" y="230" text-anchor="middle" font-family="Georgia" font-size="24" fill="#345740">The road starts where you are.</text>';$('#next-card').innerHTML='<div class="destination"><div class="handle"></div><h1>Where are we?</h1><p class="reason">'+esc(positionMessage)+'</p><button class="primary wide" id="actual-position-button">'+(positionBusy?'Waiting for your location...':'Use my location')+'</button><p class="small-note">No Arizona preview. No fixed starting city. Recommendations wait for your location. Nothing is recorded to your breadcrumb trail unless you start tracking.</p></div>';$('#actual-position-button').onclick=requestActualPosition;$('#road-note').textContent='Location permission is needed to show what is actually ahead. You can also explicitly choose a town for planning.'};
renderDiscover=function(){if(positionReady){originalDiscover();return}$('#result-count').textContent='Waiting for your location';$('#discover-list').innerHTML='<div class="list-card empty">We will not guess where you are. Enable location first to see restaurants, hotels, and starred stops ahead.</div>';$('#more-results').hidden=true};
function acceptActualPosition(pos){if(document.hidden)return;const point={lat:pos.coords.latitude,lon:pos.coords.longitude};if(!Number.isFinite(point.lat)||!Number.isFinite(point.lon)||pos.coords.accuracy>250||Date.now()-pos.timestamp>20000){positionMessage='Waiting for a more accurate, fresh GPS fix.';if(!positionReady)renderDrive();return}const nearest=nodes.map(n=>({n,d:KicksPlanner.distance(point,n)})).sort((a,b)=>a.d-b.d)[0];positionBusy=false;if(nearest.d>25){positionReady=false;positionFix=null;positionMessage='Your GPS location is about '+Math.round(nearest.d)+' miles from our town corridor near '+nearest.n.town+'. Choose where you want to join Route 66; we will not pretend you are already on it.';renderAll();return}const changed=!positionReady||state.current!==nearest.n.key;state.current=nearest.n.key;state.preview=false;positionReady=true;positionFix=point;current={...nearest.n,...point};if(changed){nextId=null;renderAll()}else updateCurrent();if($('#actual-gps-status'))$('#actual-gps-status').textContent='Located near '+nearest.n.town+', '+nearest.n.state+'. Your real GPS fix is in use.';}
function requestActualPosition(){if(!data||!nodes)return;if(!window.isSecureContext||!navigator.geolocation){positionBusy=false;positionMessage='Location requires the HTTPS app in a browser that supports GPS. We will not substitute a city.';renderAll();return}if(positionWatch!==null){navigator.geolocation.clearWatch(positionWatch);positionWatch=null}positionBusy=true;if(!positionReady)renderAll();positionWatch=navigator.geolocation.watchPosition(acceptActualPosition,error=>{positionBusy=false;if(error.code===1){if(positionWatch!==null)navigator.geolocation.clearWatch(positionWatch);positionWatch=null;positionReady=false;positionFix=null;positionMessage='Location permission was denied. Allow location for this site in your browser settings, then tap Use my location.';renderAll()}else if(!positionReady){positionMessage='Your location is temporarily unavailable. Try again outdoors or choose a planning town yourself.';renderAll()}if($('#actual-gps-status'))$('#actual-gps-status').textContent=positionMessage;},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
positionPanel=function(){sheet('<div class="eyebrow">START WHERE YOU ACTUALLY ARE</div><h2 class="sheet-title">Use my location.</h2><p class="sheet-intro">Your current GPS location sets where we look ahead. The app does not choose a starting city for you.</p><button class="primary wide" id="actual-refresh">Find me with GPS</button><p id="actual-gps-status" class="small-note" role="status">'+esc(positionReady?'Your current planning area is near '+current.town+'.':positionMessage)+'</p><button class="secondary wide" id="manual-planning">Or choose a town just for planning</button><label class="field">Travel direction<select id="actual-direction"><option value="1" '+(state.direction===1?'selected':'')+'>Toward Santa Monica</option><option value="-1" '+(state.direction===-1?'selected':'')+'>Toward Chicago</option></select></label>');$('#actual-refresh').onclick=requestActualPosition;$('#actual-direction').onchange=e=>{state.direction=+e.target.value;nextId=null;persist();if(positionReady)renderAll()};$('#manual-planning').onclick=()=>{manualPositionPanel();const oldSave=$('#position-save').onclick;$('#position-save').onclick=()=>{positionReady=true;positionFix=null;oldSave()}}};
openPlan=function(){if(!positionReady){positionPanel();return}originalPlan()};nightPanel=function(hotel){if(!positionReady){positionPanel();return}originalNight(hotel)};
$('#position-open').onclick=positionPanel;$('#gps-map').onclick=positionPanel;$('#plan-open').onclick=openPlan;$('#evening-open').onclick=()=>nightPanel();
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(positionWatch!==null)navigator.geolocation.clearWatch(positionWatch);positionWatch=null}else if(data)requestActualPosition()});window.addEventListener('pagehide',()=>{if(positionWatch!==null)navigator.geolocation.clearWatch(positionWatch);positionWatch=null});

async function init(){try{const r=await fetch('./catalog.json');if(!r.ok)throw Error();data=await r.json();nodes=KicksPlanner.model(data);const ids=new Set(data.places.map(p=>p.id));state.saved=state.saved.filter(x=>ids.has(x));state.visited=state.visited.filter(x=>ids.has(x));state.pins=state.pins.filter(p=>ids.has(p.id)&&p.verification==='user-confirmed'&&Number.isFinite(p.lat)&&Number.isFinite(p.lon));renderAll();requestActualPosition();if(['drive','discover','passport'].includes(location.hash.slice(1)))view(location.hash.slice(1));if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>console.info('Offline pack unavailable.'));}catch(e){$('#next-card').innerHTML='<div class="destination"><h1>The road pack could not load.</h1><p>Open this app through the GitHub Pages HTTPS address, with catalog.json alongside index.html. Try reloading while online.</p></div>';document.querySelectorAll('button').forEach(b=>b.disabled=true);console.error(e)}}init();

document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const image=e.target;const parent=image.parentElement;if(parent.classList.contains('venue-art')){image.hidden=true;parent.style.background='#dce6d4';parent.textContent='Roadside photo unavailable offline';}}},true);

